static inline void swap_ptr(void **p1, void **p2) {
  void *t = *p1;
  *p1     = *p2;
  *p2     = t;
}

static inline size_t get_super_block_size(enum ggml_type weight_type) {
  switch (weight_type) {
    case GGML_TYPE_Q4_0:
    case GGML_TYPE_IQ4_NL:
      return sizeof(my_block_q4_0);
    case GGML_TYPE_Q8_0:
      return sizeof(my_block_q8_0);
    default:
      return 0;
  }
}

static inline int64_t matmul_trace_now_us(void);

typedef struct {
  int64_t issue_us;
  int64_t wait_us;
  int64_t sync_us;
} lpbq_dma_trace_t;

static inline int64_t lpbq_dma_trace_now(bool enabled) {
  return enabled ? matmul_trace_now_us() : 0;
}

static inline void lpbq_dma_trace_add(int64_t *restrict total, int64_t t0_us, int64_t t1_us) {
  if (total && t1_us >= t0_us) {
    *total += t1_us - t0_us;
  }
}

static inline int dma_issue_load_from_ddr_ex(dma_desc_1d_t *desc, void *vtcm_dst, const void *src, size_t size,
                                             bool dst_bypass) {
  dma_wait_for_idle();

  desc->next       = 0;
  desc->length     = size;
  desc->type       = DMA_DESC_TYPE_1D;
  desc->src_bypass = 1;
  desc->dst_bypass = dst_bypass ? 1 : 0;
  desc->ordered    = 1;
  desc->dstate     = DMA_DESC_DSTATE_PENDING;
  desc->src        = (uint32_t) src;
  desc->dst        = (uint32_t) vtcm_dst;

  return dma_submit_one(desc);
}

static inline int dma_issue_load_from_ddr(dma_desc_1d_t *desc, void *vtcm_dst, const void *src, size_t size) {
  return dma_issue_load_from_ddr_ex(desc, vtcm_dst, src, size, false);
}

static inline int lpbq_dma_issue_kmajor_weight_load(dma_desc_1d_t *desc, void *vtcm_dst,
                                                    const void *src, size_t size,
                                                    bool collect_dma_trace,
                                                    lpbq_dma_trace_t *dma_trace) {
  const int64_t wait_t0 = lpbq_dma_trace_now(collect_dma_trace);
#if HTP_LPBQ_KMAJOR_WEIGHT_DMA_PREISSUE_WAIT
  dma_wait_for_idle();
#endif
  const int64_t wait_t1 = lpbq_dma_trace_now(collect_dma_trace);
  if (collect_dma_trace && dma_trace) {
    lpbq_dma_trace_add(&dma_trace->wait_us, wait_t0, wait_t1);
  }

  const int64_t issue_t0 = lpbq_dma_trace_now(collect_dma_trace);
  desc->next       = 0;
  desc->length     = size;
  desc->type       = DMA_DESC_TYPE_1D;
  desc->src_bypass = HTP_LPBQ_KMAJOR_WEIGHT_DMA_SRC_BYPASS != 0;
  desc->dst_bypass = HTP_LPBQ_KMAJOR_WEIGHT_DMA_DST_BYPASS != 0;
  desc->ordered    = 1;
  desc->dstate     = DMA_DESC_DSTATE_PENDING;
  desc->src        = (uint32_t) src;
  desc->dst        = (uint32_t) vtcm_dst;

  const int submit_ret = dma_submit_one(desc);
  const int64_t issue_t1 = lpbq_dma_trace_now(collect_dma_trace);
  if (collect_dma_trace && dma_trace) {
    lpbq_dma_trace_add(&dma_trace->issue_us, issue_t0, issue_t1);
  }
  return submit_ret;
}

static inline int dma_issue_fp16_weight_load(dma_desc_1d_t *desc, void *vtcm_dst, const void *src, size_t size,
                                             bool direct_final_buffer) {
  // Direct-FP16 pipeline writes the DMA result into the buffer consumed by HMX
  // itself. Route that experiment through the explicit dst_bypass knob; the
  // safe scratch path keeps the established cached destination behavior because
  // a following HVX publish store makes the final HMX buffer visible.
  return dma_issue_load_from_ddr_ex(desc, vtcm_dst, src, size,
                                    direct_final_buffer && (HTP_FP16_DMA_DST_BYPASS != 0));
}

static inline void lpbq_make_dma_weight_visible_to_hmx_timed(void *vtcm_dst, size_t bytes,
                                                            bool collect_dma_trace,
                                                            lpbq_dma_trace_t *dma_trace) {
  if (!vtcm_dst || bytes == 0u) {
    return;
  }
  // LPBQ deploy-v1 direct-DMA retry: the architectural path is DDR -> DMA ->
  // HMX-facing VTCM, but previous full-V6 probes let HMX observe stale bytes
  // when the final buffer had no HVX-store producer.  Keep the old HVX fallback
  // intact and add the same cache-invalidate plus ordering fence for every
  // direct-final LPBQ DMA publish, even when dst_bypass is enabled.
  const int64_t sync_t0 = lpbq_dma_trace_now(collect_dma_trace);
#if HTP_LPBQ_KMAJOR_WEIGHT_DMA_VISIBILITY_SYNC
  qurt_mem_cache_clean((qurt_addr_t) vtcm_dst, bytes, QURT_MEM_CACHE_INVALIDATE, QURT_MEM_DCACHE);
#else
  // LPBQ deploy-v1 visibility-sync A/B: do not delete the conservative
  // invalidate above. This candidate deliberately keeps only the ordering fence
  // so real-layer/smoke/P-D can decide whether the K-major DMA path needs the
  // expensive per-window cache maintenance.
#endif
  asm volatile("barrier" ::: "memory");
  const int64_t sync_t1 = lpbq_dma_trace_now(collect_dma_trace);
  if (collect_dma_trace && dma_trace) {
    lpbq_dma_trace_add(&dma_trace->sync_us, sync_t0, sync_t1);
  }
}

static inline void __attribute__((unused)) lpbq_make_dma_weight_visible_to_hmx(void *vtcm_dst, size_t bytes) {
  lpbq_make_dma_weight_visible_to_hmx_timed(vtcm_dst, bytes, false, NULL);
}

static void find_chunk_size(size_t x_max, size_t y_max, size_t xy_max, size_t x_unit, size_t y_unit, size_t *x_out,
                            size_t *y_out) {
  int64_t best_xy = 0;
  size_t  best_x = 0, best_y = 0;

  for (size_t x = x_max; x > 0; x -= x_unit) {
    size_t  y  = smin(align_down(xy_max / x, y_unit), y_max);
    int64_t xy = x * y;
    if (best_xy < xy) {
      best_xy = xy;
      best_x = x, best_y = y;
    }
  }
  *x_out = best_x, *y_out = best_y;
}

static inline bool qk_matmul_use_pipeline(int m, int k, int n) {
#if HTP_MATMUL_PIPELINE_MODE == 1
  (void) m;
  (void) k;
  (void) n;
  // Experiment mode: force the conservative sequential safe path so capacity
  // sweeps can compare it against the original auto-selected 4-stage pipeline.
  return false;
#else
  // Original policy: use the 4-stage pipeline only when M is large enough to
  // amortize scheduling overhead and K<=N gives enough N chunks to overlap.
  return (m >= 128) && (k <= n);
#endif
}

static inline bool fp16_use_decode_direct_pipeline(int m, int k, int n) {
#if HTP_FP16_DECODE_DIRECT_PIPELINE
  // Decode is m=1 GEMV-like work. The original pipeline gate above keeps
  // small-M matmuls sequential because the quantized scratch path had dmwait
  // stability issues. Pure-FP16 direct-final DMA already uses dst_bypass and a
  // 3-entry final weight ring, so this separate knob can overlap K<=N decode
  // weight DMA with HMX without changing the quantized route.
  return (m > 0) && (m <= HTP_FP16_DECODE_PIPELINE_MAX_M) && (k <= n);
#else
  (void) m;
  (void) k;
  (void) n;
  return false;
#endif
}

static inline bool fp16_use_small_m_vtcm_profile(int m) {
#if HTP_FP16_SMALL_M_VTCM_ENABLE
  // Short prefill has too few activation rows to amortize many small weight
  // chunks. Rebalance VTCM toward larger FP16 weight tiles only for small-M
  // calls; long prefill keeps the validated high-activation-capacity profile.
  return m > 0 && m <= HTP_FP16_SMALL_M_THRESHOLD;
#else
  (void) m;
  return false;
#endif
}

