  row_store[1]  = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc00, quant_scale) + 128);
  row_store[3]  = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc10, quant_scale) + 128);
  row_store[5]  = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc01, quant_scale) + 128);
  row_store[7]  = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc11, quant_scale) + 128);
  row_store[9]  = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc02, quant_scale) + 128);
  row_store[11] = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc12, quant_scale) + 128);
  row_store[13] = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc03, quant_scale) + 128);
  row_store[15] = (uint8_t) ((int) lpbq_r4_quantize_f32_to_i8_symmetric_inv(acc13, quant_scale) + 128);
#else
  row_store[1]  = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc00, quant_scale) + 128);
  row_store[3]  = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc10, quant_scale) + 128);
  row_store[5]  = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc01, quant_scale) + 128);
  row_store[7]  = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc11, quant_scale) + 128);
  row_store[9]  = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc02, quant_scale) + 128);
  row_store[11] = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc12, quant_scale) + 128);
  row_store[13] = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc03, quant_scale) + 128);
  row_store[15] = (uint8_t) ((int) quantize_f32_to_i8_symmetric(acc13, quant_scale) + 128);
#endif
