    const HVX_Vector v_rot3 = vmem((const HVX_Vector *) (rot_col3 + s));
    v_sum00 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum00, Q6_Vqf32_vmpy_VsfVsf(v_src0, v_rot0));
    v_sum01 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum01, Q6_Vqf32_vmpy_VsfVsf(v_src0, v_rot1));
    v_sum02 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum02, Q6_Vqf32_vmpy_VsfVsf(v_src0, v_rot2));
    v_sum03 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum03, Q6_Vqf32_vmpy_VsfVsf(v_src0, v_rot3));
    v_sum10 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum10, Q6_Vqf32_vmpy_VsfVsf(v_src1, v_rot0));
    v_sum11 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum11, Q6_Vqf32_vmpy_VsfVsf(v_src1, v_rot1));
