    const HVX_Vector v_rot7 = vmemu(rot_col7 + s);
    v_sum0 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum0, Q6_Vqf32_vmpy_VsfVsf(v_src, v_rot0));
    v_sum1 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum1, Q6_Vqf32_vmpy_VsfVsf(v_src, v_rot1));
    v_sum2 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum2, Q6_Vqf32_vmpy_VsfVsf(v_src, v_rot2));
    v_sum3 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum3, Q6_Vqf32_vmpy_VsfVsf(v_src, v_rot3));
    v_sum4 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum4, Q6_Vqf32_vmpy_VsfVsf(v_src, v_rot4));
    v_sum5 = Q6_Vqf32_vadd_Vqf32Vqf32(v_sum5, Q6_Vqf32_vmpy_VsfVsf(v_src, v_rot5));
