static bool lpbq_r4_tile_is_sparse_permutation(const float *restrict r4, int r4_block) {
  // Standalone modes 37/40 use a sparse sign/permutation R4 to keep reference
  // checks cheap.  Real exported LPBQ R4 sidecars are dense; sampling a few
  // columns is enough to route the standalone sparse probe back to scalar
  // without adding a full 128x128 scan to every R4 tile.
  const int sampled_cols = smin(r4_block, 4);
  for (int col = 0; col < sampled_cols; ++col) {
    int nonzero = 0;
    const float *restrict rot_col = r4 + (size_t) col * (size_t) r4_block;
    for (int row = 0; row < r4_block; ++row) {
      if (fabsf(rot_col[row]) > 1.0e-12f) {
        ++nonzero;
        if (nonzero > 1) {
          return false;
        }
      }
    }
    if (nonzero != 1) {
      return false;
    }
  }
  return true;
}
