int hmx_mat_mul_lpbq_a8w8_accumulate_rows_probe(struct HmxInt8GateResult *results, int max_results) {
  const int n_results = 8;
  const int rows_list[6] = {1, 2, 4, 8, 16, 32};
  const int warmup = 8;
  const int iters = 512;
  if (!results || max_results < n_results) {
    return -1;
  }
  memset(results, 0, (size_t) max_results * sizeof(*results));

  uint8_t *vtcm_ptr = (uint8_t *) vtcm_manager_get_vtcm_base();
  if (!vtcm_ptr) {
    results[0].selector = 13899;
    results[0].variant = 3038;
    results[0].output_kind = -1;
    return 0;
  }

  uint16_t *hmx_out = (uint16_t *) vtcm_seq_alloc(&vtcm_ptr, HMX_FP16_TILE_SIZE);
  int32_t *acc_hmx = (int32_t *) vtcm_seq_alloc(&vtcm_ptr, 32u * 32u * sizeof(int32_t));
  memset(hmx_out, 0, HMX_FP16_TILE_SIZE);
  memset(acc_hmx, 0, 32u * 32u * sizeof(int32_t));
  for (int i = 0; i < 32 * 32; ++i) {
    hmx_out[i] = (uint16_t) ((i * 7 + 13) & 0x7f);
  }

  float row32_us = 0.0f;
  float row1_us = 0.0f;
  for (int ri = 0; ri < 6; ++ri) {
    const int rows = rows_list[ri];
    memset(acc_hmx, 0, 32u * 32u * sizeof(int32_t));
    for (int w = 0; w < warmup; ++w) {
      hmx_i8_accumulate_u7_tile_hmx_layout_rows(acc_hmx, hmx_out, rows);
    }
    memset(acc_hmx, 0, 32u * 32u * sizeof(int32_t));
    const int64_t t0 = HAP_perf_get_qtimer_count();
    for (int it = 0; it < iters; ++it) {
      hmx_i8_accumulate_u7_tile_hmx_layout_rows(acc_hmx, hmx_out, rows);
    }
    const int64_t t1 = HAP_perf_get_qtimer_count();
    const float total_us = (float) HAP_perf_qtimer_count_to_us(t1 - t0);
    const float per_call_us = total_us / (float) iters;

    int64_t checksum = 0;
    const int row_pairs = rows >= 32 ? 16 : ((rows + 1) >> 1);
    const int active_i32 = row_pairs * 64;
    for (int i = 0; i < active_i32; i += 17) {
      checksum += (int64_t) acc_hmx[i];
    }
    if (rows == 1) {
      row1_us = per_call_us;
    }
    if (rows == 32) {
      row32_us = per_call_us;
    }

    struct HmxInt8GateResult *res = &results[ri];
    res->selector = 13800 + ri;
    res->variant = 3038;
    res->output_kind = 0;
    res->tile_bytes = rows;
    res->reserved = rows;
    res->expected = (float) checksum;
    res->first8[0] = (float) rows;
    res->first8[1] = per_call_us;
    res->first8[2] = total_us;
    res->first8[3] = (float) iters;
    res->first8[4] = (float) checksum;
    res->first8[5] = 0.0f;
    res->first8[6] = (float) row_pairs / 16.0f;
    res->first8[7] = (float) row_pairs;
    res->min_value = per_call_us;
    res->max_value = per_call_us;
    res->mean_value = per_call_us;
    res->rmse = 0.0f;
  }

  for (int ri = 0; ri < 6; ++ri) {
    results[ri].first8[5] = row32_us > 0.0f ? row32_us / results[ri].first8[1] : 0.0f;
  }

  memset(acc_hmx, 0, 32u * 32u * sizeof(int32_t));
  for (int w = 0; w < warmup; ++w) {
    hmx_i8_accumulate_u7_tile_hmx_layout(acc_hmx, hmx_out);
  }
  memset(acc_hmx, 0, 32u * 32u * sizeof(int32_t));
  const int64_t full_t0 = HAP_perf_get_qtimer_count();
  for (int it = 0; it < iters; ++it) {
    hmx_i8_accumulate_u7_tile_hmx_layout(acc_hmx, hmx_out);
  }
  const int64_t full_t1 = HAP_perf_get_qtimer_count();
  const float full_total_us = (float) HAP_perf_qtimer_count_to_us(full_t1 - full_t0);
  const float full_per_call_us = full_total_us / (float) iters;

  int64_t full_checksum = 0;
  for (int i = 0; i < 32 * 32; i += 17) {
    full_checksum += (int64_t) acc_hmx[i];
  }
  results[6].selector = 13806;
  results[6].variant = 3038;
  results[6].output_kind = 0;
  results[6].tile_bytes = 32;
  results[6].reserved = 6;
  results[6].expected = (float) full_checksum;
  results[6].first8[0] = 32.0f;
  results[6].first8[1] = full_per_call_us;
  results[6].first8[2] = full_total_us;
  results[6].first8[3] = (float) iters;
  results[6].first8[4] = (float) full_checksum;
  results[6].first8[5] = full_per_call_us > 0.0f ? row32_us / full_per_call_us : 0.0f;
  results[6].first8[6] = row32_us;
  results[6].first8[7] = 16.0f;
  results[6].min_value = full_per_call_us;
  results[6].max_value = full_per_call_us;
  results[6].mean_value = full_per_call_us;

  results[7].selector = 13807;
  results[7].variant = 3038;
  results[7].output_kind = 0;
  results[7].tile_bytes = 0;
  results[7].reserved = 7;
  results[7].expected = row32_us;
  results[7].first8[0] = row1_us;
  results[7].first8[1] = row32_us;
  results[7].first8[2] = row1_us > 0.0f ? row32_us / row1_us : 0.0f;
  results[7].first8[3] = row1_us > 0.0f ? row1_us / row32_us : 0.0f;
  results[7].first8[4] = full_per_call_us;
  results[7].first8[5] = full_per_call_us > 0.0f ? row32_us / full_per_call_us : 0.0f;
  results[7].first8[6] = (float) HTP_LPBQ_SMALL_M_ACCUM_ROW0_ONLY;
  results[7].first8[7] = (float) HTP_LPBQ_R4_NIBBLE_ACTIVE_ROW_ACCUM;
  results[7].min_value = row1_us;
  results[7].max_value = row32_us;
  results[7].mean_value = row32_us > 0.0f ? row1_us / row32_us : 0.0f;
  results[7].rmse = 0.0f;
  return 0;
}

