static inline HVX_Vector lpbq_standard_fht_fp16_add(HVX_Vector a, HVX_Vector b) {
  return Q6_Vhf_equals_Vqf16(Q6_Vqf16_vadd_VhfVhf(a, b));
}

static inline HVX_Vector lpbq_standard_fht_fp16_sub(HVX_Vector a, HVX_Vector b) {
  return Q6_Vhf_equals_Vqf16(Q6_Vqf16_vsub_VhfVhf(a, b));
}

static inline HVX_Vector lpbq_standard_fht_fp16_bfly_pair_stage4(HVX_Vector v) {
  const HVX_VectorPair halves = Q6_W_vdeal_VVR(v, v, -4);
  const HVX_Vector a = Q6_V_lo_W(halves);
  const HVX_Vector b = Q6_V_hi_W(halves);
  const HVX_Vector sum = lpbq_standard_fht_fp16_add(a, b);
  const HVX_Vector diff = lpbq_standard_fht_fp16_sub(a, b);
  return Q6_V_lo_W(Q6_W_vshuff_VVR(diff, sum, -4));
}

static inline HVX_Vector lpbq_standard_fht_fp16_bfly_pair_stage8(HVX_Vector v) {
  const HVX_VectorPair halves = Q6_W_vdeal_VVR(v, v, -8);
  const HVX_Vector a = Q6_V_lo_W(halves);
  const HVX_Vector b = Q6_V_hi_W(halves);
  const HVX_Vector sum = lpbq_standard_fht_fp16_add(a, b);
  const HVX_Vector diff = lpbq_standard_fht_fp16_sub(a, b);
  return Q6_V_lo_W(Q6_W_vshuff_VVR(diff, sum, -8));
}

static inline HVX_Vector lpbq_standard_fht_fp16_bfly_pair_stage16(HVX_Vector v) {
  const HVX_VectorPair halves = Q6_W_vdeal_VVR(v, v, -16);
  const HVX_Vector a = Q6_V_lo_W(halves);
  const HVX_Vector b = Q6_V_hi_W(halves);
  const HVX_Vector sum = lpbq_standard_fht_fp16_add(a, b);
  const HVX_Vector diff = lpbq_standard_fht_fp16_sub(a, b);
  return Q6_V_lo_W(Q6_W_vshuff_VVR(diff, sum, -16));
}

static inline HVX_Vector lpbq_standard_fht_fp16_bfly_pair_stage32(HVX_Vector v) {
  const HVX_VectorPair halves = Q6_W_vdeal_VVR(v, v, -32);
  const HVX_Vector a = Q6_V_lo_W(halves);
  const HVX_Vector b = Q6_V_hi_W(halves);
  const HVX_Vector sum = lpbq_standard_fht_fp16_add(a, b);
  const HVX_Vector diff = lpbq_standard_fht_fp16_sub(a, b);
  return Q6_V_lo_W(Q6_W_vshuff_VVR(diff, sum, -32));
}

static inline HVX_Vector lpbq_standard_fht_fp16_bfly_pair_stage64(HVX_Vector v) {
  const HVX_VectorPair halves = Q6_W_vdeal_VVR(v, v, -64);
  const HVX_Vector a = Q6_V_lo_W(halves);
  const HVX_Vector b = Q6_V_hi_W(halves);
  const HVX_Vector sum = lpbq_standard_fht_fp16_add(a, b);
  const HVX_Vector diff = lpbq_standard_fht_fp16_sub(a, b);
  return Q6_V_lo_W(Q6_W_vshuff_VVR(diff, sum, -64));
}

static inline HVX_Vector lpbq_standard_fht_fp16_prefix32_pair(HVX_Vector v) {
  v = lpbq_standard_fht_fp16_bfly_pair_stage4(v);
  v = lpbq_standard_fht_fp16_bfly_pair_stage8(v);
  v = lpbq_standard_fht_fp16_bfly_pair_stage16(v);
  v = lpbq_standard_fht_fp16_bfly_pair_stage32(v);
  v = lpbq_standard_fht_fp16_bfly_pair_stage64(v);
  return v;
}

