static void __attribute__((unused))
lpbq_macro_kgroup_producer_worker(void *data, int worker_index) {
  (void) worker_index;
  lpbq_macro_kgroup_producer_state_t *st = (lpbq_macro_kgroup_producer_state_t *) data;
  const int64_t t0 = matmul_trace_now_us();
  st->result = lpbq_macro_kgroup_producer_run(st) ? 0 : -1;
  st->produce_us = matmul_trace_now_us() - t0;
  worker_pool_synctoken_jobdone(&st->sync_ctx);
}

static bool __attribute__((unused))
lpbq_macro_kgroup_producer_submit(lpbq_macro_kgroup_producer_state_t *st) {
  if (!lpbq_macro_kgroup_producer_supported(st)) {
    return false;
  }
  st->result = -1;
  st->produce_us = 0;
  worker_pool_synctoken_init(&st->sync_ctx, 1);
  worker_pool_job_t job;
  job.fptr = lpbq_macro_kgroup_producer_worker;
  job.dptr = st;
  const AEEResult submit_ret = worker_pool_submit(NULL, job);
  if (submit_ret != AEE_SUCCESS) {
    // Keep the serial producer loop as the fallback when the worker pool is not
    // available; do not run inline here because the point of this knob is
    // overlap, not a different producer implementation.
    worker_pool_synctoken_jobdone(&st->sync_ctx);
    worker_pool_synctoken_wait(&st->sync_ctx);
    return false;
  }
  return true;
}
