#endif
                  quantize_lpbq_a8w8_activation_tile_r4_hmx_u8_v6_k32_cached(
                    a_hmx_base, r4_scaled_src_cache, m, rb_mr, kt, r4_tile, r4_block,
                    act_scale, use_hvx_r4_dot);
