            const int8_t *restrict full_v6_issue_src = w_hmx_full_u8_issue;
#endif

            int64_t th0 = collect_trace_timing ? matmul_trace_now_us() : 0;
            int64_t tw0 = collect_trace_timing ? matmul_trace_now_us() : 0;
            int64_t th_expand0 = collect_hmx_grouped_v6_coarse_subtrace ? matmul_trace_now_us() : 0;
            bool full_v6_current_published_by_overlap_dma = false;
